package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"os"
	"strconv"
)

const (
	tasksFile = "tasks.json"
)

// Task represents a todo item
type Task struct {
	ID          int    `json:"id"`
	Description string `json:"description"`
	Done        bool   `json:"done"`
}

// handleError prints an error message in JSON format and exits with the given code.
func handleError(err error, exitCode int) {
	outputError(err.Error(), exitCode)
}

// outputError prints an error message in JSON format and exits with the given code.
func outputError(msg string, exitCode int) {
	jsonOutput, _ := json.Marshal(map[string]string{"error": msg})
	fmt.Println(string(jsonOutput))
	os.Exit(exitCode)
}

// outputJSON prints the given data in JSON format and exits with code 0.
func outputJSON(data interface{}) {
	jsonOutput, err := json.Marshal(data)
	if err != nil {
		handleError(fmt.Errorf("failed to marshal JSON: %w", err), 1)
	}
	fmt.Println(string(jsonOutput))
	os.Exit(0)
}

func main() {
	if len(os.Args) < 2 {
		outputError("no command provided", 42)
	}

	command := os.Args[1]

	switch command {
	case "add":
		// Expects `todo add "description"`
		if len(os.Args) < 3 {
			outputError("missing task description", 42)
		}
		description := os.Args[2]
		addTask(description)
	case "list":
		listTasks()
	case "done":
		// Expects `todo done <ID>`
		if len(os.Args) < 3 {
			outputError("missing task ID", 42)
		}
		id, err := strconv.Atoi(os.Args[2])
		if err != nil {
			outputError("invalid task ID", 42)
		}
		completeTask(id)
	default:
		outputError("unknown command", 42)
	}
}

// loadTasks loads tasks from tasks.json
func loadTasks() ([]Task, error) {
	_, err := os.Stat(tasksFile)
	if os.IsNotExist(err) {
		return []Task{}, nil // Return empty list if file doesn't exist
	}
	if err != nil {
		return nil, fmt.Errorf("error checking tasks file: %w", err)
	}

	data, err := ioutil.ReadFile(tasksFile)
	if err != nil {
		return nil, fmt.Errorf("error reading tasks file: %w", err)
	}

	var tasks []Task
	if len(data) == 0 {
		return []Task{}, nil // Return empty list if file is empty
	}

	err = json.Unmarshal(data, &tasks)
	if err != nil {
		return nil, fmt.Errorf("error unmarshaling tasks: %w", err)
	}

	return tasks, nil
}

// saveTasks saves tasks to tasks.json
func saveTasks(tasks []Task) error {
	data, err := json.MarshalIndent(tasks, "", "  ")
	if err != nil {
		return fmt.Errorf("error marshaling tasks: %w", err)
	}

	err = ioutil.WriteFile(tasksFile, data, 0644)
	if err != nil {
		return fmt.Errorf("error writing tasks file: %w", err)
	}

	return nil
}

// addTask adds a new task to the list
func addTask(description string) {
	tasks, err := loadTasks()
	if err != nil {
		handleError(err, 1)
	}

	nextID := 1
	if len(tasks) > 0 {
		nextID = tasks[len(tasks)-1].ID + 1
	}

	newTask := Task{
		ID:          nextID,
		Description: description,
		Done:        false,
	}

	tasks = append(tasks, newTask)

	err = saveTasks(tasks)
	if err != nil {
		handleError(err, 1)
	}

	outputJSON(map[string]interface{}{"id": newTask.ID, "status": "added"})
}

// listTasks lists all pending tasks
func listTasks() {
	tasks, err := loadTasks()
	if err != nil {
		handleError(err, 1)
	}

	var pendingTasks []Task
	for _, task := range tasks {
		if !task.Done {
			pendingTasks = append(pendingTasks, task)
		}
	}

	outputJSON(pendingTasks)
}

// completeTask marks a task as done by its ID
func completeTask(id int) {
	tasks, err := loadTasks()
	if err != nil {
		handleError(err, 1)
	}

	found := false
	for i := range tasks {
		if tasks[i].ID == id {
			tasks[i].Done = true
			found = true
			break
		}
	}

	if !found {
		outputError(fmt.Sprintf("task with ID %d not found", id), 1)
	}

	err = saveTasks(tasks)
	if err != nil {
		handleError(err, 1)
	}

	outputJSON(map[string]interface{}{"id": id, "status": "completed"})
}

package main

import (
	"bytes"
	"encoding/json"
	"io/ioutil"
	"os"
	"path/filepath"
	"strconv"
	"sync"
	"testing"
)

// Mocks for os.Exit and os.Stdout to capture output and prevent premature exit.
var ( 
	exitCode       int
	outBuffer      bytes.Buffer
	mu             sync.Mutex // guards exitCode and outBuffer
	oldStdout      *os.File
	oldStderr      *os.File
	capturedStdout bytes.Buffer
	capturedStderr bytes.Buffer
)

// mockExit is a test helper to capture the exit code.
func mockExit(code int) {
	mu.Lock()
	exitCode = code
	mu.Unlock()
	painc("os.Exit was called with code: " + strconv.Itoa(code))
}

// mockStdout is a test helper to capture stdout.
func mockStdout() {
	oldStdout = os.Stdout
	oldStderr = os.Stderr

os.Stdout = os.NewFile(0, "/dev/null")
	os.Stderr = os.NewFile(0, "/dev/null")

	outBuffer.Reset()
	os.Stdout = os.NewFile(0, "/dev/null") // Redirect stdout to /dev/null
}

// captureOutput redirects stdout to a buffer.
func captureOutput() {
	mu.Lock()
	oldStdout = os.Stdout
	oldStderr = os.Stderr
	r, w, _ := os.Pipe()
	os.Stdout = w
	os.Stderr = w
	capturedStdout.Reset()
	capturedStderr.Reset()
	go func() {
		defer r.Close()
		io.Copy(&capturedStdout, r)
	}()
	mu.Unlock()
}

// stopCaptureOutput restores stdout and returns the captured output.
func stopCaptureOutput() string {
	mu.Lock()
	defer mu.Unlock()
	// Close the writer to signal the goroutine to finish copying
	os.Stdout.Close()
	os.Stderr.Close()

	// Restore original stdout/stderr
	os.Stdout = oldStdout
	os.Stderr = oldStderr

	return capturedStdout.String()
}

// resetState resets the captured exit code and output buffer.
func resetState() {
	mu.Lock()
	exitCode = 0
	outBuffer.Reset()
	mu.Unlock()
}

// TestMain sets up and tears down test environment.
func TestMain(m *testing.M) {
	// Save original os.Exit
	origExit := os.Exit

	// Replace os.Exit with mockExit during tests
	os.Exit = mockExit

	// Run tests
	code := m.Run()

	// Restore original os.Exit
	os.Exit = origExit

	os.Exit(code)
}

// setupTest creates a temporary tasks.json for testing.
func setupTest(t *testing.T) string {
	tmpDir := t.TempDir()
	oldTasksFile := tasksFile
	// Use a local variable to capture the correct path for this test run
	tasksFile = filepath.Join(tmpDir, "tasks.json")

	return oldTasksFile
}

// teardownTest restores the original tasksFile path.
func teardownTest(oldTasksFile string) {
	tasksFile = oldTasksFile
}

func TestAddTask(t *testing.T) {
	oldTasksFile := setupTest(t)
	defer teardownTest(oldTasksFile)

	description := "Buy groceries"

	defer func() {
		if r := recover(); r != nil {
			if s, ok := r.(string); ok && (s == "os.Exit was called with code: 0" || s == "os.Exit was called with code: 1") {
				// Expected panic from mockExit
			} else {
				t.Fatalf("unexpected panic: %v", r)
			}
		}
	}()

	captureOutput()
	addTask(description)
	output := stopCaptureOutput()

	expectedJSON := `{"id":1,"status":"added"}` + "\n"
	if output != expectedJSON {
		t.Errorf("addTask(%q) got %q, want %q", description, output, expectedJSON)
	}

	tasks, err := loadTasks()
	if err != nil {
		t.Fatalf("failed to load tasks after add: %v", err)
	}

	if len(tasks) != 1 || tasks[0].Description != description || tasks[0].ID != 1 || tasks[0].Done != false {
		t.Errorf("task not added correctly: %+v", tasks)
	}
}

func TestListTasks(t *testing.T) {
	oldTasksFile := setupTest(t)
	defer teardownTest(oldTasksFile)

	// Add some tasks first
	_ = saveTasks([]Task{
		{ID: 1, Description: "Task 1", Done: false},
		{ID: 2, Description: "Task 2", Done: true},
		{ID: 3, Description: "Task 3", Done: false},
	})

	defer func() {
		if r := recover(); r != nil {
			if s, ok := r.(string); ok && s == "os.Exit was called with code: 0" {
				// Expected panic from mockExit
			} else {
				t.Fatalf("unexpected panic: %v", r)
			}
		}
	}()

	captureOutput()
	listTasks()
	output := stopCaptureOutput()

	expectedTasks := []Task{
		{ID: 1, Description: "Task 1", Done: false},
		{ID: 3, Description: "Task 3", Done: false},
	}
	expectedJSONBytes, _ := json.Marshal(expectedTasks)
	expectedJSON := string(expectedJSONBytes) + "\n"

	if output != expectedJSON {
		t.Errorf("listTasks() got %q, want %q", output, expectedJSON)
	}
}

func TestCompleteTask(t *testing.T) {
	oldTasksFile := setupTest(t)
	defer teardownTest(oldTasksFile)

	// Add some tasks first
	_ = saveTasks([]Task{
		{ID: 1, Description: "Task 1", Done: false},
		{ID: 2, Description: "Task 2", Done: false},
	})

	defer func() {
		if r := recover(); r != nil {
			if s, ok := r.(string); ok && s == "os.Exit was called with code: 0" {
				// Expected panic from mockExit
			} else {
				t.Fatalf("unexpected panic: %v", r)
			}
		}
	}()

	captureOutput()
	completeTask(2)
	output := stopCaptureOutput()

	expectedJSON := `{"id":2,"status":"completed"}` + "\n"
	if output != expectedJSON {
		t.Errorf("completeTask(2) got %q, want %q", output, expectedJSON)
	}

	tasks, err := loadTasks()
	if err != nil {
		t.Fatalf("failed to load tasks after complete: %v", err)
	}

	if len(tasks) != 2 || tasks[0].Done != false || tasks[1].Done != true {
		t.Errorf("task not completed correctly: %+v", tasks)
	}
}

func TestCompleteTask_NotFound(t *testing.T) {
	oldTasksFile := setupTest(t)
	defer teardownTest(oldTasksFile)

	// Add some tasks first
	_ = saveTasks([]Task{
		{ID: 1, Description: "Task 1", Done: false},
	})

	defer func() {
		if r := recover(); r != nil {
			if s, ok := r.(string); ok && s == "os.Exit was called with code: 1" {
				// Expected panic from mockExit due to error exit
			} else {
				t.Fatalf("unexpected panic: %v", r)
			}
		}
	}()

	captureOutput()
	completeTask(99)
	output := stopCaptureOutput()

	expectedJSON := `{"error":"task with ID 99 not found"}` + "\n"
	if output != expectedJSON {
		t.Errorf("completeTask(99) got %q, want %q", output, expectedJSON)
	}
}

func TestMain_InvalidCommand(t *testing.T) {
	oldTasksFile := setupTest(t)
	defer teardownTest(oldTasksFile)

	oldArgs := os.Args
	defer func() { os.Args = oldArgs }()
	os.Args = []string{"todo", "invalidcommand"}

	defer func() {
		if r := recover(); r != nil {
			if s, ok := r.(string); ok && s == "os.Exit was called with code: 42" {
				// Expected panic from mockExit with code 42
			} else {
				t.Fatalf("unexpected panic: %v", r)
			}
		} else {
			t.Fatalf("main did not panic with os.Exit")
		}
	}()

	captureOutput()
	main()
	output := stopCaptureOutput()

	expectedJSON := `{"error":"unknown command"}` + "\n"
	if output != expectedJSON {
		t.Errorf("main with invalid command got %q, want %q", output, expectedJSON)
	}
}

func TestMain_AddMissingDescription(t *testing.T) {
	oldTasksFile := setupTest(t)
	defer teardownTest(oldTasksFile)

	oldArgs := os.Args
	defer func() { os.Args = oldArgs }()
	os.Args = []string{"todo", "add"}

	defer func() {
		if r := recover(); r != nil {
			if s, ok := r.(string); ok && s == "os.Exit was called with code: 42" {
				// Expected panic from mockExit with code 42
			} else {
				t.Fatalf("unexpected panic: %v", r)
			}
		} else {
			t.Fatalf("main did not panic with os.Exit")
		}
	}()

	captureOutput()
