	defer func() {
		if r := recover(); r != nil {
			if s, ok := r.(string); ok && s == "os.Exit was called with code: 42" {
				// Expected panic from mockExit with code 42
			} else {
				t.Fatalf("unexpected panic: %v", r)
			}
		} else {
			t.Fatalf("main did not panic with os.Exit")
		}
	}()

